get(key) {
  const entry = entries.get(key)
  if (entry === undefined) return undefined
  const now = clock()
  if (now > entry.expiresAt) {
    // TTL has passed: treat as a miss and drop the expired entry.
    entries.delete(key)
    return undefined
  }
  // Refresh recency: re-insert so the key moves to the MRU end of the Map.
  entries.delete(key)
  entries.set(key, entry)
  entry.lastUsed = now
  return entry.value
},
set(key, value) {
  const now = clock()
  if (entries.has(key)) {
    // Re-insert so the key moves to the MRU end of the Map.
    entries.delete(key)
  } else if (entries.size >= capacity) {
    // Evict the least-recently-used entry: the first key in recency order.
    const oldest = entries.keys().next().value
    entries.delete(oldest)
  }
  entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
},

args.old_string:
get(key) {
  const entry = entries.get(key)
  if (entry === undefined) return undefined
  entry.lastUsed = clock()
  return entry.value
},
set(key, value) {
  const now = clock()
  if (entries.size >= capacity && !entries.has(key)) {
    // evict one entry to make room
    const victim = [...entries.entries()].sort((a, b) => b[1].lastUsed - a[1].lastUsed)[0]
    entries.delete(victim[0])
  }
  entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
},

